// Interface icons are Lucide (ISC, lucide.dev). The app uses an SVG sprite,
// app/icons/lucide.svg, holding only the icons referenced here, in
// app/index.html (a use element pointing into the sprite) and in calls to icon(); it is
// generated by scripts/vendor-icons.mjs from the lucide-static package.
// Stroke, fill and size come from CSS (svg.icon in app.css).

export const ICON_SPRITE = 'icons/lucide.svg';

// Step kinds (core/timeline.mjs toolKind) → Lucide icon.
export const KIND_ICONS = Object.freeze({
  shell: 'square-terminal',
  read: 'file-text',
  edit: 'pencil',
  search: 'search',
  web: 'globe',
  git: 'git-branch',
  agent: 'bot',
  plan: 'list-checks',
  tool: 'wrench'
});

const NAME = /^[a-z0-9-]+$/;

/** Markup for one sprite icon; `name` is a Lucide icon id. */
export function icon(name, className = '') {
  if (!NAME.test(name)) throw new Error('Bad icon name: ' + name);
  return '<svg class="icon' + (className ? ' ' + className : '') + '" aria-hidden="true" focusable="false"><use href="' + ICON_SPRITE + '#' + name + '"/></svg>';
}

export function kindIcon(kind) {
  return icon(KIND_ICONS[kind] || KIND_ICONS.tool);
}
